#include "docker/DockerManager.h"
#include "process/ProcessRunner.h"
#include <string>
namespace lvk::docker { namespace { std::wstring q(const std::string& value){return L"\""+std::wstring(value.begin(),value.end())+L"\"";} } bool DockerManager::engineRunning()const{const auto docker=process::findOnPath(L"docker");return !docker.empty()&&process::runHidden(docker,L"info").exitCode==0;}bool DockerManager::imageReady()const{const auto docker=process::findOnPath(L"docker");return !docker.empty()&&process::runHidden(docker,L"image inspect "+q(image_)).exitCode==0;}bool DockerManager::rebuild(const std::filesystem::path& folder,std::string& error)const{const auto docker=process::findOnPath(L"docker");if(docker.empty()){error="Docker CLI not found.";return false;}const auto result=process::runHidden(docker,L"build -t "+q(image_)+L" "+q(folder.string()));if(!result.started||result.exitCode!=0){error="docker build failed.";if(!result.output.empty())error+="\n"+result.output;return false;}return true;} }
